assertions.test:
(() => {
    const section = document.querySelector("#status")?.parentElement;
    if (!section) return false;
    const row = (label) => [...section.querySelectorAll("tbody tr")]
      .find((r) => r.querySelector("th")?.textContent.trim() === label);
    const normative = row("Normative source");
    const guide = row("Chrome developer guide");
    const chromium = row("Chromium behavior");
    const shipping = row("Shipping and intent record");
    return !!normative?.querySelector('a[href="https://w3c.github.io/webappsec-dbsc/"]') &&
      /Editor’s Draft/.test(normative.textContent) &&
      !!guide?.querySelector('a[href="https://developer.chrome.com/docs/web-platform/device-bound-session-credentials"]') &&
      /2025-04-15/.test(guide.textContent) &&
      !!chromium?.querySelector('a[href="https://source.chromium.org/chromium/chromium/src/+/main:net/device_bound_sessions/registration_fetcher.cc"]') &&
      /not portable requirements/.test(chromium.textContent) &&
      !!shipping?.querySelector('a[href="https://chromestatus.com/feature/5140168270413824"]') &&
      /In development/.test(shipping.textContent) &&
      /desktop milestone 145/.test(shipping.textContent) &&
      /Android milestone that is null\/unknown/.test(shipping.textContent);
  })()
